  const totalPricePerMonth = Math.round((totalCostPerMonth + profitAmount) * 100) / 100;
  const pricePerVisit = bidVisitsPerMonth > 0 ? Math.round(totalPricePerMonth / bidVisitsPerMonth * 100) / 100 : totalPricePerMonth;
