/**
 * Look up facility phrases for a given FacilityType string.
 * Returns the 'other' fallback if the type is unrecognized.
 */
export function getFacilityPhrases(facilityType?: string): FacilityPhrases {
    if (!facilityType) return FACILITY_PHRASE_MAP.other;
    return FACILITY_PHRASE_MAP[facilityType as FacilityType] ?? FACILITY_PHRASE_MAP.other;
}

/**
 * Infer a canonical FacilityType from a free-text search query string.
 * Used during prospecting import to auto-categorize businesses.
 * Order matters — most specific patterns are matched first.
 */
export function inferFacilityType(searchQuery?: string): FacilityType | null {
    if (!searchQuery) return null;
    const q = searchQuery.toLowerCase();
    if (q.includes('dialysis')) return 'medical_dialysis';
    if (q.includes('urgent care')) return 'medical_urgent_care';
    if (q.includes('surgery') || q.includes('surgical')) return 'medical_surgery';
    if (q.includes('dental') || q.includes('dentist')) return 'medical_dental';
    if (q.includes('veterinary') || q.includes('vet clinic') || q.includes('animal hospital')) return 'medical_veterinary';
    if (q.includes('physical therapy') || q.includes('physical therapist') || q.includes('physiotherapy') || q.includes('pt clinic') || q.includes('rehab center') || q.includes('rehabilitation')) return 'medical_physical_therapy';
    if (q.includes('chiropractic') || q.includes('chiropractor')) return 'medical_private';
    if (q.includes('medical') || q.includes('doctor') || q.includes('physician') || q.includes('clinic')) return 'medical_private';
    if (q.includes('daycare') || q.includes('preschool') || q.includes('childcare')) return 'edu_daycare';
    if (q.includes('tutoring') || q.includes('tutor') || q.includes('learning center') || q.includes('educational center') || q.includes('test prep') || q.includes('kumon') || q.includes('mathnasium') || q.includes('sylvan')) return 'edu_tutoring';
    if (q.includes('school') || q.includes('academy')) return 'edu_private_school';
    if (q.includes('dealership') || q.includes('auto dealer') || q.includes('car dealer')) return 'auto_dealer_showroom';
    if (q.includes('auto service') || q.includes('auto repair') || q.includes('mechanic')) return 'auto_service_center';
    if (q.includes('cleanroom') || q.includes('lab ')) return 'lab_cleanroom';
    if (q.includes('bsl') || q.includes('biosafety')) return 'lab_bsl';
    if (q.includes('manufacturing') || q.includes('factory') || q.includes('warehouse')) return 'manufacturing_light';
    if (q.includes('gym') || q.includes('fitness') || q.includes('crossfit') || q.includes('yoga') || q.includes('pilates')) return 'fitness_gym';
    if (q.includes('retail') || q.includes('store') || q.includes('shop') || q.includes('boutique')) return 'retail_storefront';
    if (q.includes('church') || q.includes('religious') || q.includes('mosque') || q.includes('synagogue') || q.includes('temple') || q.includes('worship')) return 'religious_center';
    if (q.includes('funeral') || q.includes('mortuary') || q.includes('cremation')) return 'funeral_home';
    if (q.includes('office')) return 'office_general';
    return null;
}

export type LeadStatus = 'new' | 'contacted' | 'qualified' | 'walkthrough' | 'proposal' | 'quoted' | 'won' | 'lost' | 'churned';

export type LeadType = 'direct' | 'tenant' | 'referral_partnership' | 'enterprise';

export interface Lead {
    id?: string;
    businessName: string;
    facilityType: FacilityType; // MUST use the enum above
    contactName: string;
    contactPhone: string;
    email: string;
    zipCode: string;
    address?: string;      // Street address
    city?: string;         // City / Town
    state?: string;        // 2-letter state abbrev
    zip?: string;          // ZIP code (from parsed address)
    serviceInterest?: string; // e.g. "janitorial", "floor_care"
    preferredAuditTimes?: Date[]; // Array of 3 options
    notes?: string;

    // Growth Engine Attribution
    attribution: {
        source: string;        // e.g. "google", "linkedin"
        medium: string;        // e.g. "cpc", "qr_code"
        campaign: string;
        landingPage: string;
    };

    createdAt: Date;
    status: LeadStatus;
    leadType?: LeadType;   // 'direct' (default) | 'tenant' | 'referral_partnership' | 'enterprise'

    // Operations linkage
    locations?: ClientLocation[];
    assignedFsmId?: string;
    contractId?: string;
    wonAt?: any;

    // Property Sourcing Enrichment (populated when attribution.source = 'property_sourcing')
    propertySourcing?: {
        sourceProvider: string;     // "attom", "reonomy", "mock"
        sourcePropertyId?: string;  // Provider's unique ID
        squareFootage?: number;
        yearBuilt?: number;
        ownerName?: string;
        tenantName?: string;
        tenantCount?: number;
        lastSalePrice?: number;
        lastSaleDate?: string;
        sourcedAt: Date;
    };

    // Sales Outreach Sequence
    outreachStatus?: 'PENDING' | 'SENT' | 'REPLIED' | 'NEEDS_MANUAL';
    outreachSentAt?: Date;

    // Sales → FSM Handoff (auto-set on first work order assignment)
    handedOffToFsm?: string;     // FSM staffId
    handoffDate?: Date;

    // Public Calculator Lead Data
    sqft?: string;
    source?: string;  // e.g. 'calculator_client', 'calculator_contractor', 'audit_form'
    calculatorData?: {
        daysPerWeek?: number;
        monthlyEstimate?: number;
        monthlyLow?: number;
        monthlyHigh?: number;
    };

    // External Integrations (Xero / Mercury)
    externalIds?: {
        xeroContactId?: string;
    };

    // Contact-centric migration: FK to primary contact
    primaryContactId?: string;

    // Service capabilities the company needs / offers
    serviceCapabilities?: string[];
}

