// --- PROPERTY SOURCING ---

/** Provider-agnostic, normalized property record returned by any data provider */
export interface RawProperty {
    name: string;              // Building or business name
    address: string;           // Full street address
    city: string;
    state: string;
    zip: string;
    propertyType?: string;     // "medical_office", "retail", "auto_dealership", etc.
    squareFootage?: number;
    yearBuilt?: number;
    ownerName?: string;        // Building owner (for outreach)
    ownerPhone?: string;
    ownerEmail?: string;
    tenantName?: string;       // Current occupant (if single-tenant)
    tenantCount?: number;      // 1 = single-tenant
    lotSize?: number;          // In sq ft or acres
    lastSalePrice?: number;
    lastSaleDate?: string;
    source: string;            // "attom", "reonomy", "mock", etc.
    sourceId?: string;         // Provider's unique property ID
    rawData?: Record<string, any>; // Full provider response for debugging
}

/** Extended property with UI-specific state for the sourcing campaign table */
export interface PreviewProperty extends RawProperty {
    id: string;                // Client-generated unique ID
    isDismissed?: boolean;
    fitScore?: number;         // AI-assessed fit (0-100)
    aiReasoning?: string;      // AI explanation of the fit score
    facilityType?: string;     // Mapped XIRI facility type
}


// --- COMMISSION & COMPENSATION ---

/** Stored at Firestore: settings/commissions */
export interface CommissionConfig {
    rateStandard: number;          // e.g. 0.05 (5%) for deals ≤ MRR threshold
    ratePremium: number;           // e.g. 0.075 (7.5%) for deals > MRR threshold
    mrrThreshold: number;          // e.g. 3000 ($3K MRR boundary)
    fsmUpsellRate: number;         // e.g. 0.05 (5% of annualized upsell)
    clawbackMonths: number;        // e.g. 6
    payoutSplit: number[];         // e.g. [50, 25, 25]
    updatedAt?: Date;
    updatedBy?: string;
}

export type CommissionType = 'SALES_NEW' | 'FSM_UPSELL' | 'FSM_RETENTION';
export type CommissionStatus = 'PENDING' | 'ACTIVE' | 'COMPLETED' | 'PARTIALLY_CANCELLED';
export type PayoutStatus = 'PENDING' | 'PAID' | 'CANCELLED';

export interface PayoutEntry {
    month: number;                // 0, 1, 2
    amount: number;
    percentage: number;           // 50, 25, 25
    status: PayoutStatus;
    scheduledAt: Date;
    paidAt?: Date;
}

export interface Commission {
    id?: string;
    staffId: string;              // Who earns the commission
    staffRole: 'sales' | 'fsm';
    quoteId: string;              // Source quote
    leadId: string;               // Related lead/client
    type: CommissionType;

    // Financial
    mrr: number;                  // Monthly Recurring Revenue (for tier calc)
    acv: number;                  // Annual Contract Value (mrr × 12 or face value)
    rate: number;                 // 0.10, 0.15, or 0.05
    totalCommission: number;      // acv × rate

    // Payout schedule (Sales: 50/25/25 over 3 months)
    payoutSchedule: PayoutEntry[];

    // Clawback (6-month window — cancel unpaid portions only)
    clawbackWindowEnd: Date;      // 6 months from quote acceptance
    status: CommissionStatus;

    createdAt: Date;
    updatedAt: Date;
}

export interface CommissionLedgerEntry {
    id?: string;
    commissionId: string;
    type: 'PAYOUT_SCHEDULED' | 'PAYOUT_PAID' | 'PAYOUT_CANCELLED' | 'CLAWBACK';
    amount: number;
    staffId: string;
    description: string;
    createdAt: Date;
}

// NRR (Net Revenue Retention) for FSM quarterly bonus
export interface NrrSnapshot {
    id?: string;
    fsmId: string;                // FSM staffId
    quarter: string;              // e.g. "2026-Q1"
    startingMrr: number;
    endingMrr: number;
    upsells: number;
    downgrades: number;
    churn: number;
    nrr: number;                  // (start + upsells - downgrades - churn) / start
    bonusRate: number;            // 0, 0.005, 0.01, 0.02
    bonusAmount: number;
    calculatedAt: Date;
}

// --- LEAD PROSPECTING ---

export type EmailSource =
    | 'mailto'
    | 'structured_data'
    | 'regex'
    | 'ai_extraction'
    | 'serper_search'
    | 'serper_facebook'
    | 'facebook_scrape'
    | 'hunter'
    | 'snov'
    | 'pattern_guess'
    | 'none';

export type EmailConfidence = 'high' | 'medium' | 'low';

/** A single prospect discovered and enriched by the prospecting pipeline */
/**
 * A single contact discovered during enrichment.
 * Hunter.io / Snov.io return up to 10 emails per domain search (1 credit),
 * so we store them all instead of discarding 90% of what we paid for.
 */
export interface ProspectContact {
    email: string;
    firstName?: string;
    lastName?: string;
    position?: string;       // "Office Manager", "Owner", etc.
    confidence?: number;     // 0-100 from the provider
    type: 'personal' | 'generic';
    provider: string;        // "hunter", "snov", "ai_extraction", "mailto", "serper"
}

export interface EnrichedProspect {
    // Business info (from Google Places / Serper)
    businessName: string;
    address?: string;
    phone?: string;
    website?: string;
    rating?: number;
    userRatingsTotal?: number;
    facilityType?: FacilityType;

    // Primary contact (best email — owner / decision-maker)
    contactName?: string;       // "Dr. John Smith"
    contactTitle?: string;      // "Owner", "Managing Director"
    contactEmail?: string;      // "jsmith@business.com"

    // Fallback
    genericEmail?: string;      // "info@business.com"

    // All contacts discovered (from Hunter/Snov domain search + scraping)
    allContacts?: ProspectContact[];

    // Social
    facebookUrl?: string;
    linkedinUrl?: string;

    // Enrichment metadata
    emailSource: EmailSource;
    emailConfidence: EmailConfidence;
    enrichmentLog?: string[];   // Trace of steps tried — useful for debugging
}

// --- VENDOR PROSPECTING ---

/** A vendor prospect discovered and enriched by the vendor prospecting pipeline */
export interface VendorProspect {
    // Identity
    businessName: string;
    normalizedName: string;

    // Contact
    contactName?: string;
    contactEmail?: string;
    genericEmail?: string;
    phone?: string;

    // Location
    address?: string;
    city?: string;
    state?: string;

    // Online presence
    website?: string;
    facebookUrl?: string;
    linkedinUrl?: string;

    // Capabilities (normalized to canonical VENDOR_CAPABILITIES values)
    detectedCapabilities: string[];   // e.g. ['plumbing', 'hvac']
    searchCapability: string;         // The capability value used in the search query
    isCommercial?: boolean;           // AI-determined: commercial focus?

    // Ratings
    rating?: number;
    reviewCount?: number;

    // All contacts discovered
    allContacts?: ProspectContact[];

    // Enrichment metadata
    emailSource: EmailSource;
    emailConfidence: EmailConfidence;
    enrichmentLog: string[];

    // Pipeline
    status: 'pending_review' | 'approved' | 'rejected';
    batchDate: string;
    searchQuery: string;
    searchLocation: string;
    createdAt: Date;
}
